/// <summary>
///    AVA <c>avaCheckMaxAgeCalcDays</c> method.
/// </summary>
void avaCheckMaxAgeCalcDays()
{
    AVASalesParameters  locAVASalesParameters;
    InventTable         locInventTable;
    TransDate           locHK2Date;
    TransDate           locSystemDate;

    locAVASalesParameters   = AVASalesParameters::find();
    locInventTable          = salesLine.inventTable(salesLine.ItemId);

    if (!salesLine.AVAItemSetComponent)
    {
        if (KCS_ItemUsageIDs::find(locInventTable.KCS_ItemUsageID).KCS_ItemNonStd)      // is featured item?
        {
            locHK2Date          = salesLine.KCS_PriceDate;
            locHK2Date          = locInventTable.avaGetHK2Date();                       // 2009:locHK2Date = locInventTable.KCS_GetHK2Date();

            locSystemDate       = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

            if ((locSystemDate - locHK2Date) > locAVASalesParameters.MaxAgeFeaturedItemCalculation)
            {
                if (!locHK2Date)
                {
                    warning(strfmt( "@NDX:NXAFeaturedItemCalculationP1MissingPrice",
                                salesLine.ItemId                                )   );
                }
                else
                {
                    warning(strfmt("@NDX:NXAFeaturedItemCalculationP1PriceOlderThanP2",
                                salesLine.ItemId,
                                locAVASalesParameters.MaxAgeFeaturedItemCalculation )   );
                }
            }
        }
    }
}
